mapper.select:
SELECT u.id, u.username, u.fullname, u.email, u.enabled, u.account_locked AS accountLocked, u.last_login AS lastLogin, u.created_by AS createdBy, u.created_date AS createdDate, u.updated_by AS updatedBy, u.updated_date AS updatedDate, u.tenant_id AS tenantId FROM users u WHERE u.deleted = false AND u.tenant_id = #{tenantId}
AND (u.username ILIKE '%' || #{keyword} || '%' OR u.fullname ILIKE '%' || #{keyword} || '%' OR u.email ILIKE '%' || #{keyword} || '%')
ORDER BY u.created_date DESC LIMIT #{limit} OFFSET #{offset}
